'use strict';
(function(){
  const B=window.PhysicsBank,L=(en,ta)=>lang==='ta'?ta:en,text=o=>o[lang];
  let history=[],storageOK=true,current=B.make('energy-1'),selected=null,assisted=false;
  try{history=B.clean(JSON.parse(localStorage.getItem('iyal-practice-v1')||'[]'))}catch{storageOK=false}
  const past=()=>current.source!==null;
  const same=(a,q)=>a.id===q.id&&B.make(a.id,a.variant).prompt.en===q.prompt.en;
  const recorded=()=>history.find(a=>!a.viewed&&same(a,current));
  const root=document.createElement('section');root.id='exam-practice';root.className='practice-section';
  root.innerHTML=`<div class="practice-heading"><div><div class="section-label">04 <span id="practice-label"></span></div><h2 id="practice-title"></h2><p id="practice-intro"></p></div><a class="back-lab" href="#scene" id="back-lab"></a></div><div class="prep-grid"><section class="question-panel"><div class="practice-toolbar"><button id="past-question" class="secondary"></button><button id="adaptive-question" class="primary"></button></div><p id="bank-note" class="small-note"></p><div class="filter-row"><label for="skill-filter" id="filter-label"></label><select id="skill-filter"></select><button id="new-variant" class="secondary"></button></div><div class="question-meta"><span id="question-origin" class="origin-badge"></span><span id="question-skill"></span></div><h3 id="question-prompt" tabindex="-1"></h3><div id="question-graph"></div><p id="question-conditions" class="small-note"></p><p id="question-source"></p><form id="practice-form"><fieldset id="choice-field"><legend id="choice-label"></legend><div id="practice-choices"></div></fieldset><div id="numeric-field"><label for="practice-number" id="numeric-label"></label><div class="number-entry"><input id="practice-number" type="number" step="any" inputmode="decimal" autocomplete="off"><span id="practice-unit"></span></div></div><div class="question-actions"><button type="submit" id="check-practice" class="primary"></button><button type="button" id="show-solution" class="secondary"></button></div></form><div id="practice-feedback" role="status" aria-live="polite"></div><div id="worked-answer" hidden></div><button id="next-practice" class="primary" hidden></button></section><aside id="study-plan" class="study-panel"><div class="section-label">05 <span id="plan-label"></span></div><h2 id="plan-title"></h2><div class="score-grid"><div><strong id="score-accuracy"></strong><span id="accuracy-label"></span></div><div><strong id="score-coverage"></strong><span id="coverage-label"></span></div></div><div id="skill-progress"></div><div id="recommendation" role="status" aria-live="polite"></div><p id="recommendation-detail"></p><p id="other-topics"></p><details><summary id="rules-title"></summary><p id="rules-copy"></p></details><p id="saved-note" class="small-note"></p><button id="clear-progress" class="text-button"></button></aside></div>`;
  document.querySelector('footer').before(root);
  const jump=document.createElement('a');jump.href='#exam-practice';jump.className='practice-jump';document.querySelector('.title-row').after(jump);
  function save(){try{localStorage.setItem('iyal-practice-v1',JSON.stringify(history))}catch{storageOK=false}}
  function setQuestion(q){current=q;selected=null;assisted=false;$('practice-number').value='';$('practice-feedback').textContent='';renderQuestion();$('question-prompt').focus({preventScroll:true})}
  function graph(q){if(!q.graph){$('question-graph').replaceChildren();return}const {start,end,duration}=q.graph;const min=Math.min(end,0)-5,max=Math.max(start,0)+5,Y=v=>140-(v-min)/(max-min)*115,y0=Y(0);$('question-graph').innerHTML=`<svg viewBox="0 0 350 175" role="img" aria-label="${L('Vertical velocity plotted against time','நிலைக்குத்து வேகம்–நேரம் வரைபு')}"><line x1="52" y1="20" x2="52" y2="145" stroke="#5c7076"/><line x1="52" y1="${y0}" x2="315" y2="${y0}" stroke="#5c7076"/><line x1="52" y1="${Y(start)}" x2="285" y2="${Y(end)}" stroke="#006c65" stroke-width="3"/><text x="35" y="${Y(start)+4}" text-anchor="end">${start}</text><text x="35" y="${Y(end)+4}" text-anchor="end">${end}</text><text x="56" y="${y0+17}">0</text><text x="281" y="${y0+17}">${duration}</text><text x="300" y="${y0-8}">t (s)</text><text x="53" y="14">vᵧ (m/s)</text></svg>`}
  function renderQuestion(){
    assisted=assisted||history.some(a=>a.assisted&&same(a,current));
    const done=recorded();$('question-origin').textContent=past()?L('2024 · Paper I · Q3','2024 · பகுதி I · வினா 3'):L('AI-authored practice','AI உருவாக்கிய பயிற்சி');
    $('question-skill').textContent=text(B.families[current.family]);$('question-prompt').textContent=text(current.prompt);
    $('question-conditions').textContent=current.type==='numeric'&&!past()?L('Use g = 10 m/s². Ignore air resistance. Enter a number; round to 2 decimal places if needed. The simulator above uses g = 9.81.','g = 10 m/s² எனக் கொள்க. வளித்தடையைப் புறக்கணிக்கவும். தேவைப்பட்டால் 2 தசம இடங்களுக்கு விடையளிக்கவும். மேலுள்ள உருவகப்படுத்தலில் g = 9.81.'):L('Ignore air resistance.','வளித்தடையைப் புறக்கணிக்கவும்.');
    $('question-source').replaceChildren();if(past()){const a=document.createElement('a');a.href=B.source;a.target='_blank';a.rel='noopener';a.textContent=L('View original paper on e-thaksalawa ↗','e-thaksalawa இல் அசல் வினாத்தாளைப் பார்க்கவும் ↗');$('question-source').append(a,document.createTextNode(L(' · Adapted wording and numeric answer entry; Iyal worked solution, not the official marking scheme.',' · சொற்றொடரும் விடையளிக்கும் முறையும் மாற்றப்பட்டுள்ளன; இயலின் விளக்கம், உத்தியோகபூர்வ மதிப்பீட்டுத் திட்டம் அல்ல.')))}
    $('choice-field').hidden=current.type!=='choice';$('numeric-field').hidden=current.type!=='numeric';$('practice-number').disabled=!!done;$('practice-number').required=current.type==='numeric'&&!done;$('practice-unit').textContent=current.unit;
    $('practice-choices').replaceChildren();if(current.type==='choice')current.options.forEach((option,i)=>{const label=document.createElement('label'),input=document.createElement('input'),span=document.createElement('span');input.type='radio';input.name='practice-choice';input.value=i;input.checked=selected===i;input.disabled=!!done;input.addEventListener('change',()=>selected=i);span.textContent=text(option);label.append(input,span);$('practice-choices').append(label)});
    $('check-practice').disabled=!!done;$('show-solution').disabled=!!done||assisted;$('next-practice').hidden=!done;$('worked-answer').hidden=!(done||assisted);$('worked-answer').textContent=text(current.explain);
    if(done)renderFeedback(done);else if(assisted)$('practice-feedback').textContent=L('Solution viewed. You can still answer, but this attempt will not count toward readiness.','விளக்கம் பார்க்கப்பட்டது. விடையளிக்கலாம்; இம்முயற்சி தயார்நிலை மதிப்பீட்டில் சேராது.');
    graph(current);
  }
  function renderFeedback(a){$('practice-feedback').className=a.correct?'correct':'needs-work';$('practice-feedback').textContent=(a.correct?L('Correct. ','சரி. '):L('Not quite. Review the method below. ','முழுமையாகச் சரியில்லை. கீழுள்ள முறையைப் பார்க்கவும். '))+(a.assisted?L('Assisted practice — excluded from readiness.','உதவியுடன் செய்த பயிற்சி — தயார்நிலையில் சேராது.'):L('First attempt recorded. Repeating this exact question does not add evidence.','முதல் முயற்சி பதிவாகியது. இதே வினாவை மீண்டும் செய்வதால் மதிப்பீடு உயராது.'))}
  function renderPlan(){
    const s=B.evaluate(history);$('score-accuracy').textContent=s.total?s.accuracy+'%':'—';$('score-coverage').textContent=s.total+'/18';$('skill-progress').replaceChildren();
    for(const skill of s.skills){const row=document.createElement('div');row.className='skill-row';const label=document.createElement('span'),status=document.createElement('span');label.textContent=text(B.families[skill.id]);status.textContent=skill.total?skill.correct+'/'+skill.total+' '+L('correct','சரி'):L('Not assessed','மதிப்பிடப்படவில்லை');status.className=skill.secure?'skill-secure':'';row.append(label,status);$('skill-progress').append(row)}
    const weak=s.skills.filter(k=>!k.secure);$('recommendation').className=s.ready?'ready':'developing';
    $('recommendation').textContent=s.reviewDue?L('Time for a short review','சிறு மீளாய்வுக்கான நேரம்'):s.ready?L('Ready to shift some study time','வேறு பகுதிகளுக்கும் நேரம் ஒதுக்கலாம்'):s.total?L('Keep building topic confidence','இத்தலைப்பில் மேலும் பயிற்சி செய்யுங்கள்'):L('Let’s establish your starting point','உங்கள் தற்போதைய புரிதலை மதிப்பிடுவோம்');
    $('recommendation-detail').textContent=s.reviewDue?L('Your last evidence is at least 2 days old. Try fresh questions before reducing revision further.','கடைசி மதிப்பீட்டிலிருந்து 2 நாட்கள் கடந்துள்ளன. மீளாய்வை மேலும் குறைப்பதற்கு முன் புதிய வினாக்களை முயலுங்கள்.'):s.ready?L('You met this prototype’s projectile-motion threshold across all six skills. Spend more time diagnosing another topic and keep a short projectile review in 2 days. This is a topic signal, not a predicted exam grade.','ஆறு திறன்களிலும் இம்முன்மாதிரியின் எறிய இயக்க அளவுகோலை அடைந்துள்ளீர்கள். வேறு தலைப்பைப் பரிசோதிக்க அதிக நேரம் ஒதுக்கி, 2 நாட்களில் எறிய இயக்கத்தைச் சுருக்கமாக மீளாய்வு செய்யுங்கள். இது தேர்வுப் பெறுபேறு முன்னறிவிப்பு அல்ல.'):L('Next practice targets: ','அடுத்த பயிற்சிக்கான பகுதிகள்: ')+(weak.length?weak.map(k=>text(B.families[k.id])).join(' · '):L('improve accuracy with fresh variants.','புதிய வினாக்களால் துல்லியத்தை உயர்த்துங்கள்.'));
    $('other-topics').textContent=L('Other areas: circuits, waves and forces have not been assessed here. Choose your next topic with your teacher; this prototype cannot rank those areas yet.','மற்ற பகுதிகள்: மின்சுற்றுகள், அலைகள், விசைகள் இங்கு மதிப்பிடப்படவில்லை. ஆசிரியருடன் அடுத்த தலைப்பைத் தேர்ந்தெடுக்கவும்; இம்முன்மாதிரி அவற்றை இன்னும் தரவரிசைப்படுத்தாது.');
    $('saved-note').textContent=storageOK?L('Progress is saved only in this browser. No student account or cloud sync.','முன்னேற்றம் இந்த உலாவியில் மட்டும் சேமிக்கப்படும். மாணவர் கணக்கோ மேக ஒத்திசைவோ இல்லை.'):L('Browser storage is unavailable. Progress lasts only for this session.','உலாவிச் சேமிப்பு கிடைக்கவில்லை. இவ்வமர்வில் மட்டும் முன்னேற்றம் இருக்கும்.');
  }
  function render(){
    const copy={
      'practice-label':['EXAM PRACTICE','பரீட்சைப் பயிற்சி'],'practice-title':['From understanding to answering','புரிதலிலிருந்து விடையளித்தலுக்கு'],'practice-intro':['Start with a past-paper connection, then practise different ways the same physics can be tested.','கடந்த வினாத்தாள் தொடர்புடன் தொடங்கி, ஒரே கருத்தைச் சோதிக்கும் பல வகை வினாக்களைப் பயிற்சி செய்யுங்கள்.'],
      'back-lab':['↑ Back to experiment','↑ பரிசோதனைக்குச் செல்க'],'past-question':['Past-paper question','கடந்த வினாத்தாள் வினா'],'adaptive-question':['Suggest a practice question','பயிற்சி வினாவைப் பரிந்துரைக்கவும்'],
      'bank-note':['18 question styles across 6 skills. AI-authored templates with calculated variants; no live AI generation. Educator review pending.','6 திறன்களில் 18 வினா வகைகள். AI உருவாக்கிய மாதிரிகளிலிருந்து கணக்கிடப்பட்ட மாறுபாடுகள்; நேரடி AI உருவாக்கம் இல்லை. ஆசிரியர் மீளாய்வு நிலுவையில்.'],
      'filter-label':['Practise a skill','திறனைத் தேர்க'],'new-variant':['Try another question','வேறு வினாவை முயல்க'],'choice-label':['Select one answer','ஒரு விடையைத் தேர்க'],'numeric-label':['Your answer','உங்கள் விடை'],'check-practice':['Check answer','விடையைச் சரிபார்க்கவும்'],'show-solution':['Show worked solution','விளக்கத்தைக் காட்டுக'],'next-practice':['Next recommended question →','அடுத்த பரிந்துரைக்கப்பட்ட வினா →'],
      'plan-label':['YOUR STUDY PLAN','உங்கள் கற்றல் திட்டம்'],'plan-title':['Where to focus next','அடுத்து எதில் கவனம் செலுத்துவது'],'accuracy-label':['Independent accuracy','உதவியற்ற துல்லியம்'],'coverage-label':['Question styles assessed','மதிப்பிட்ட வினா வகைகள்'],'rules-title':['How is this recommendation made?','பரிந்துரை எவ்வாறு உருவாகிறது?'],
      'rules-copy':['Shift-focus threshold: at least 12 different question styles, at least 85% correct overall, and 2 correct styles in each of 6 skills. Only first attempts on fresh questions without a revealed solution count. A new numerical variant can replace older evidence for its style, but never increases style coverage. Evidence expires after 14 days. These prototype thresholds are not educationally validated.','கவனத்தை மாற்றும் அளவுகோல்: குறைந்தது 12 வேறுபட்ட வினா வகைகள், மொத்தத்தில் 85% சரியான விடைகள், ஒவ்வொரு 6 திறனிலும் 2 சரியான வகைகள். விளக்கம் பார்க்காமல் புதிய வினாக்களில் செய்யும் முதல் முயற்சிகள் மட்டும் சேரும். புதிய எண் மாறுபாடு பழைய மதிப்பீட்டை மாற்றலாம்; வகைகளின் எண்ணிக்கையை உயர்த்தாது. மதிப்பீடு 14 நாட்களில் காலாவதியாகும். இவ்வளவுகோல்கள் கல்வியியல் ரீதியாகச் சரிபார்க்கப்படவில்லை.'],
      'clear-progress':['Clear this browser’s progress','இந்த உலாவியின் முன்னேற்றத்தை நீக்குக']};
    for(const[id,values]of Object.entries(copy))$(id).textContent=L(...values);jump.textContent=L('Practise exam questions & see your study plan ↓','பரீட்சை வினாக்களும் கற்றல் திட்டமும் ↓');
    const filter=$('skill-filter'),old=filter.value;filter.replaceChildren();for(const[id,label]of Object.entries({all:{en:'All skills · adaptive',ta:'அனைத்துத் திறன்கள்'},...B.families})){const option=document.createElement('option');option.value=id;option.textContent=text(label);filter.append(option)}filter.value=old||'all';renderQuestion();renderPlan();
  }
  function next(){const q=B.next(history,$('skill-filter').value);if(q)setQuestion(q);else $('practice-feedback').textContent=L('You have attempted all fresh questions in this selection. Choose another skill or review your worked answers.','இத்தேர்விலுள்ள அனைத்துப் புதிய வினாக்களையும் முயன்றுள்ளீர்கள். வேறு திறனைத் தேர்ந்தெடுக்கவும் அல்லது விளக்கங்களை மீளாய்வு செய்யவும்.')}
  $('past-question').addEventListener('click',()=>setQuestion(B.make('energy-1',0)));
  $('adaptive-question').addEventListener('click',next);$('next-practice').addEventListener('click',next);$('skill-filter').addEventListener('change',next);
  $('new-variant').addEventListener('click',()=>{const relevant=B.ids.filter(id=>$('skill-filter').value==='all'||id.startsWith($('skill-filter').value+'-'));const i=relevant.indexOf(current.id);setQuestion(B.make(relevant[(i+1)%relevant.length],current.variant))});
  $('show-solution').addEventListener('click',()=>{assisted=true;history.push({id:current.id,variant:current.variant,correct:false,assisted:true,viewed:true,at:Date.now()});save();renderQuestion();renderPlan()});
  $('practice-form').addEventListener('submit',e=>{e.preventDefault();if(recorded())return;const result=B.grade(current,current.type==='choice'?selected:$('practice-number').value);if(!result.valid){$('practice-feedback').textContent=L('Enter a number or select an answer before checking.','சரிபார்ப்பதற்கு முன் எண்ணை உள்ளிடவும் அல்லது விடையைத் தேர்க.');return}history.push({id:current.id,variant:current.variant,correct:result.correct,assisted,at:Date.now()});history=history.slice(-600);save();renderQuestion();renderPlan()});
  $('clear-progress').addEventListener('click',()=>{if(!confirm(L('Clear all practice results saved in this browser?','இந்த உலாவியில் சேமித்த அனைத்துப் பயிற்சி முடிவுகளையும் நீக்கவா?')))return;history=[];save();setQuestion(B.make('energy-1'));renderPlan()});
  window.addEventListener('iyal-language',render);window.addEventListener('focus',renderPlan);render();
})();
